require_once '../config/database.php'; require_once '../config/helpers.php'; require_role('admin');
function count_rows($conn,$sql){$r=mysqli_query($conn,$sql);return $r?(int)mysqli_fetch_row($r)[0]:0;}
$totalStudents=count_rows($conn,"SELECT COUNT(*) FROM users WHERE role='student'");
$totalSubjects=count_rows($conn,"SELECT COUNT(*) FROM subjects");
$totalEnrollments=count_rows($conn,"SELECT COUNT(*) FROM enrollments");
$recent=mysqli_query($conn,"SELECT id,student_no,full_name,username FROM users WHERE role='student' ORDER BY id DESC LIMIT 6");
?>
